/// <summary>
/// One open transfer order. Direction is OUT when it ships from the requested warehouse, IN when it is bound for it.
/// </summary>
[DataContractAttribute]
class HSMobileOpsTransferSummaryRow
{
    str        transferId;
    str        fromWarehouseId;
    str        toWarehouseId;
    str        status;
    str        shipDate;
    str        receiveDate;
    int        lineCount;
    str        direction;
}

Method.Source:
[DataMemberAttribute('TransferId')]
public str parmTransferId(str _value = transferId)
{
    transferId = _value;
    return transferId;
}

[DataMemberAttribute('FromWarehouseId')]
public str parmFromWarehouseId(str _value = fromWarehouseId)
{
    fromWarehouseId = _value;
    return fromWarehouseId;
}

[DataMemberAttribute('ToWarehouseId')]
public str parmToWarehouseId(str _value = toWarehouseId)
{
    toWarehouseId = _value;
    return toWarehouseId;
}

[DataMemberAttribute('Status')]
public str parmStatus(str _value = status)
{
    status = _value;
    return status;
}

[DataMemberAttribute('ShipDate')]
public str parmShipDate(str _value = shipDate)
{
    shipDate = _value;
    return shipDate;
}

[DataMemberAttribute('ReceiveDate')]
public str parmReceiveDate(str _value = receiveDate)
{
    receiveDate = _value;
    return receiveDate;
}

[DataMemberAttribute('LineCount')]
public int parmLineCount(int _value = lineCount)
{
    lineCount = _value;
    return lineCount;
}

[DataMemberAttribute('Direction')]
public str parmDirection(str _value = direction)
{
    direction = _value;
    return direction;
}
